def largest_free_square(plan):
    rows, cols = len(plan), len(plan[0])
    best = 0
    for r in range(rows):
        for c in range(cols):
            k = 1
            while r + k <= rows and c + k <= cols:
                if not all(plan[i][j] == '.' for i in range(r, r + k) for j in range(c, c + k)):
                    break
                best = max(best, k)
                k += 1
    return best
